// Computes the maximum value among the first `n` elements of `a`.
// Assumptions (as stated in the problem):
// - n > 0
// - n <= a.len()
// - n < 1000
fn max(a: &Vec<i32>, n: usize) -> i32 {
    debug_assert!(n > 0);
    debug_assert!(n <= a.len());
    debug_assert!(n < 1000);

    let mut m = a[0];
    for i in 1..n {
        if a[i] > m {
            m = a[i];
        }
    }
    m
}

fn main() {
    let a = vec![3, -1, 10, 7, 4];
    let n = 4;
    let m = max(&a, n);
    println!("max among first {} elements = {}", n, m); // 10
}